---@class Dyreparken
local ns = select(2, ...)

-- The backgrounds' probe (development only, never packaged: #@do-not-package@ in the TOC). It extends
-- ns.Scenes. /dp probe bg opens the gallery (Dev/SceneGallery.lua) on every large picture the client has
-- (Dev/SceneArt.lua, generated by tools/scene_art.py, 2026-11-21): a family's suggestions first, then each
-- group (Forever's own loading screens, every loading screen, the dungeon journal, atlases). The thumbnails are
-- cut to the card's shape as the card will show them; hovering one shows it on the card (Scenes.override, which
-- a release never sets), a click makes it the family's (DyreparkenDB.scenePicks; luajit tools/sv.lua picks
-- prints them as code, with the Scenes.ART rows they need).
---@class Dyreparken.Scenes
local Scenes = ns.Scenes
local Art = ns.SceneArt

-- The generated crops (files', and an atlas's that's part of its rectangle) join Scenes.ART, so a pick shows
-- here as it will once its row is in the code.
for _, row in ipairs(Art.list) do
    local whole = row[4] == 0 and row[5] == 1 and row[6] == 0 and row[7] == 1
    if (type(row[1]) == "number" or not whole) and not Scenes.ART[row[1]] then
        Scenes.ART[row[1]] = { row[4], row[5], row[6], row[7], row[8], row[9] }
    end
end

-- Every candidate once, numbered, in the generated order: { n, path, group, label, w, h }.
function Scenes:Candidates()
    if self.candidates then return self.candidates end
    local list = {}
    for i, row in ipairs(Art.list) do
        list[i] = { n = i, path = row[1], group = row[2], label = row[3], w = row[8], h = row[9] }
    end
    self.candidates = list
    return list
end

-- A family's suggestions: its pick now, what the code has (BY_FAMILY), then the generated ones. A candidate
-- that's in no list (a path in the code) gets an entry of its own.
function Scenes:Suggestions(family)
    local byPath, out, seen = {}, {}, {}
    for _, c in ipairs(self:Candidates()) do byPath[c.path] = c end
    local function Add(spec)
        if spec == nil or seen[spec] then return end
        seen[spec] = true
        out[#out + 1] = byPath[spec] or { n = 0, path = spec, group = "code", label = tostring(spec) }
    end
    Add(ns.DB.global.scenePicks[family])
    for _, spec in ipairs(self.BY_FAMILY[family] or {}) do Add(spec) end
    for _, spec in ipairs(Art.families[family] or {}) do Add(spec) end
    return out
end

-- The card's shape (width / height) for the thumbnails: the scene's own once laid out, else a guess.
function Scenes:Shape()
    local scene = ns.JournalUI:Card().scene
    local w, h = scene and scene:GetWidth(), scene and scene:GetHeight()
    if w and h and w > 40 and h > 40 then return w / h end
    return 0.8
end

-- Show a candidate on every card (nil: the families again).
function Scenes:Preview(spec)
    if spec == nil then self.override = nil
    else self.override = function() return spec end end
    ns.JournalUI:Refresh()
end

-- /dp probe bg: the gallery, on the family of the pet on the card. /dp probe bg off: no preview.
function Scenes:Probe(arg)
    if arg == "off" then
        self:Preview(nil)
        return ns.Print("Backgrounds: back to the families.")
    end
    ns.SceneGallery:Show(self:Candidates(), "bg", ns.JournalUI:Card().family)
    ns.Print(("%d backgrounds (%s). Hover one to see it on the card; click to pick it for the family."):format(
        #self:Candidates(), Art.build or "?"))
end
